import { z } from "zod";

export const getAddLocationFormSchema = (t: any) => z.object({
  locationName: z.string().min(1, t("validation.required")),
  googleMapLink: z.string()
    .min(1, t("validation.required"))
    .refine(
      (url) => {
        const trimmed = url.trim();
        return /^https?:\/\//.test(trimmed) && (
          /google\.[a-z.]+\/maps/i.test(trimmed) ||
          /maps\.google\.[a-z.]+/i.test(trimmed) ||
          /goo\.gl\/maps/i.test(trimmed) ||
          /maps\.app\.goo\.gl/i.test(trimmed)
        );
      },
      { message: t("locations.validation.invalidMapLinkFormat") }
    ),
  cityId: z.string().min(1, t("validation.required")),
  areaId: z.string().min(1, t("validation.required")),
  latitude: z.string().optional()
    .refine((val) => !val || !isNaN(Number(val)), { message: t("validation.numeric") }),
  longitude: z.string().optional()
    .refine((val) => !val || !isNaN(Number(val)), { message: t("validation.numeric") }),
  northSide: z.string().optional(),
  southSide: z.string().optional(),
  eastSide: z.string().optional(),
  westSide: z.string().optional(),
  landmark: z.string().optional(),
  description: z.string().optional(),
});

export type AddLocationFormInput = z.infer<ReturnType<typeof getAddLocationFormSchema>>;
